  'dash.settings.autonomous_confirm': 'Chuyển sang chế độ Tự động?\n\nĐiều này tự động phê duyệt mọi danh mục công cụ — bash, git, file_write, file_edit, database_query, browser, http_request — bao gồm cả tập con phá hủy của chúng (rm, format, deletes, overwrites). Các hoạt động duy nhất vẫn yêu cầu xác nhận là các mẫu không thể đảo ngược (force-push, hard reset, history rewrites, package publish, git_commit --amend) — những thứ đó không bao giờ được miễn xác nhận.\n\nChỉ chọn điều này nếu bạn muốn Ava chạy mà không cần xác nhận trong các phiên dài, và chỉ trên một workspace nơi bạn có thể khôi phục từ việc ghi sai qua git.',
