  'dash.settings.custom_model': 'Mô hình Tùy chỉnh',
  'dash.settings.custom_model_desc': 'Trỏ Ava đến bất kỳ mô hình nào — cục bộ (Ollama, LM Studio, vLLM trên máy của bạn) hoặc từ xa (cụm vLLM riêng tư, tinh chỉnh tự lưu trữ, OpenRouter, Together, bất cứ thứ gì hỗ trợ API OpenAI Chat Completions). Máy chủ cục bộ vẫn ở trên máy của bạn; điểm cuối từ xa nhận bảo mật tùy theo điểm cuối của bạn cung cấp. Khởi động lại bảng trò chuyện sau khi lưu để thay đổi có hiệu lực.',
