  'dash.settings.dataset_capture_desc': 'Ghi lại lựa chọn công cụ của Ava, chuyển giao nhân cách, thao tác bộ nhớ, v.v. vào ~/.ava/datasets/. Mặc định chỉ cục bộ. Không bao giờ ghi lại lời nhắc hoặc tệp của bạn — chỉ quyết định của cô ấy và ngữ cảnh chỉ hình dạng.',
